const CUSTOM_PROMISIFY = '__mochiPromisify__';

export function inspect(value, options = {}) {
    const depth = Number(options.depth ?? 2);
    const seen = new Set();

    function render(item, level) {
        if (item === null) return 'null';
        if (item === undefined) return 'undefined';
        const type = typeof item;
        if (type === 'string') return options.quoteStrings === false ? String(item) : JSON.stringify(item);
        if (type === 'number' || type === 'boolean' || type === 'bigint') return String(item);
        if (type === 'function') return `[Function: ${item.name || 'anonymous'}]`;
        if (type === 'symbol') return String(item);
        if (item instanceof Error) return `${item.name}: ${item.message}`;
        if (level > depth) return Array.isArray(item) ? '[Array]' : '[Object]';
        if (seen.has(item)) return '[Circular]';
        seen.add(item);
        try {
            if (Array.isArray(item)) {
                const parts = item.map((entry) => render(entry, level + 1));
                return `[ ${parts.join(', ')} ]`;
            }
            if (item instanceof Uint8Array || (item && item.type === 'Buffer' && Array.isArray(item.data))) {
                const bytes = item instanceof Uint8Array ? item : item.data;
                const preview = Array.from(bytes.slice(0, 32)).join(', ');
                return `<Buffer ${preview}${bytes.length > 32 ? ', ...' : ''}>`;
            }
            const keys = Object.keys(item);
            const parts = keys.map((key) => {
                const val = render(item[key], level + 1);
                return /^[A-Za-z_$][\w$]*$/.test(key) ? `${key}: ${val}` : `${JSON.stringify(key)}: ${val}`;
            });
            return `{ ${parts.join(', ')} }`;
        } finally {
            seen.delete(item);
        }
    }

    return render(value, 0);
}

export function format(...args) {
    if (!args.length) return '';
    let index = 0;
    let text = String(args[index++]);
    if (typeof text !== 'string') {
        return [text, ...args.slice(index)].map((part) => inspect(part)).join(' ');
    }
    const extras = args.slice(index);
    let extra = 0;
    text = text.replace(/%[sdjoO%]/g, (token) => {
        if (token === '%%') return '%';
        if (extra >= extras.length) return token;
        const value = extras[extra++];
        if (token === '%s') return typeof value === 'string' ? value : inspect(value, { quoteStrings: false });
        if (token === '%d') return String(Number(value));
        if (token === '%j') {
            try { return JSON.stringify(value); } catch (e) { return '[Circular]'; }
        }
        return inspect(value);
    });
    while (extra < extras.length) text += ` ${inspect(extras[extra++])}`;
    return text;
}

export function promisify(original) {
    if (typeof original !== 'function') throw new TypeError('promisify expects a function');
    if (original[CUSTOM_PROMISIFY]) return original;
    const fn = function (...args) {
        return new Promise((resolve, reject) => {
            original.apply(this, [...args, (err, ...values) => {
                if (err) return reject(err);
                resolve(values.length > 1 ? values : values[0]);
            }]);
        });
    };
    fn[CUSTOM_PROMISIFY] = original;
    return fn;
}

export function callbackify(original) {
    if (typeof original !== 'function') throw new TypeError('callbackify expects a function');
    return function (...args) {
        const callback = args.pop();
        Promise.resolve(original.apply(this, args)).then(
            (value) => callback(null, value),
            (error) => callback(error),
        );
    };
}

export function once(fn) {
    let called = false;
    let result;
    return function (...args) {
        if (called) return result;
        called = true;
        result = fn.apply(this, args);
        return result;
    };
}

export function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}

export function inherits(ctor, superCtor) {
    ctor.prototype = Object.create(superCtor && superCtor.prototype, {
        constructor: { value: ctor, writable: true, configurable: true },
    });
}

export function randomId(bytes = 8) {
    const out = [];
    for (let i = 0; i < bytes; i++) out.push(Math.floor(Math.random() * 256).toString(16).padStart(2, '0'));
    return out.join('');
}

export const types = {
    isPromise(value) {
        return !!value && typeof value.then === 'function';
    },
    isUint8Array(value) {
        return value instanceof Uint8Array;
    },
    isError(value) {
        return value instanceof Error;
    },
};

export function debuglog(section) {
    return function log(...args) {
        if (globalThis.__MOCHI_DEBUG__ === true || globalThis.__MOCHI_DEBUG__ === section) {
            console.error(`[${section}]`, format(...args));
        }
    };
}

export const isDeepStrictEqual = (a, b) => inspect(a, { depth: 32 }) === inspect(b, { depth: 32 });

export function deprecate(fn, msg) { let warned=false; return function(...a){ if(!warned){ warned=true; try{console.warn(msg);}catch{} } return fn.apply(this,a); }; }
export function _extend(target, source) { for (const k in source) target[k]=source[k]; return target; }
export const TextEncoder = globalThis.TextEncoder;
export const TextDecoder = globalThis.TextDecoder;

export default {
    deprecate,
    _extend,
    TextEncoder,
    TextDecoder,
    inspect,
    format,
    promisify,
    callbackify,
    once,
    sleep,
    inherits,
    randomId,
    types,
    debuglog,
    isDeepStrictEqual,
};
